    pg.fill('#diario-nota','Texto bem longo '+('palavrasemespacoqueforcaquebra'*6)+' '+('muito texto '*30)); pg.click('#form-diario button[type=submit]'); pg.wait_for_timeout(200); fechar(pg)
    m=pg.evaluate("[document.documentElement.scrollWidth<=window.innerWidth+1,[...document.querySelectorAll('#diario-lista .timeline-item')].every(i=>i.getBoundingClientRect().right<=window.innerWidth)]")
    ok('G4a Mobile: texto longo no diário não quebra o layout', all(m), m)
    pg.screenshot(path='m_diario.png',full_page=True)
    pg.set_viewport_size({'width':1280,'height':900}); ir(pg,'tela-diario')
    pg.fill('#diario-nota','Segunda anotação'); pg.click('#form-diario button[type=submit]'); pg.wait_for_timeout(200); fechar(pg)
    al=pg.evaluate("(()=>{const it=[...document.querySelectorAll('#diario-lista .timeline-item')];const L=it.map(i=>Math.round(i.querySelector('.timeline-content').getBoundingClientRect().left));const M=it.map(i=>Math.round(i.querySelector('.timeline-mark').getBoundingClientRect().left));return {n:it.length,L:[...new Set(L)],M:[...new Set(M)]}})()")
    ok('G4b Desktop: títulos/datas/descrições dos registros alinhados na mesma coluna', al['n']>=2 and len(al['L'])==1 and len(al['M'])==1, al)
