    ir(pg,'tela-fotos'); pg.screenshot(path='d_fotos.png',full_page=True)
    ir(pg,'tela-minha-plantinha'); pg.screenshot(path='d_plantas.png',full_page=True)
    ctx.close()
    b.close()
